export function isAllowedTool(toolName: string, allowedTools?: string[]): boolean {
  return !allowedTools || allowedTools.includes(toolName);
}

export function formatPromptValue(value: unknown): string {
  if (value === null) {
    return 'null';
  }
  if (Array.isArray(value)) {
    return `[${value.map(formatPromptValue).join(',')}]`;
  }
  if (typeof value === 'object') {
    const record = value as Record<string, unknown>;
    return `{${Object.keys(record)
      .sort()
      .map((key) => `${key}:${formatPromptValue(record[key])}`)
      .join(',')}}`;
  }
  if (typeof value === 'string') {
    return `"${value.replaceAll('\\', '\\\\').replaceAll('"', '\\"')}"`;
  }
  if (typeof value === 'number' || typeof value === 'boolean' || typeof value === 'bigint') {
    return String(value);
  }
  if (typeof value === 'undefined') {
    return 'undefined';
  }
  return Object.prototype.toString.call(value);
}

export function parseToolArgs(rawArgs: string): Record<string, unknown> {
  try {
    return JSON.parse(rawArgs || '{}');
  } catch {
    return {};
  }
}

import { AbiBuilderService } from './abi/abi-builder.service';
import { validateAbiPayload } from './abi/abi-validator';

type UnknownRecord = Record<string, unknown>;

export async function buildUnifiedAgentCognitiveState(params: {
  abiBuilder: AbiBuilderService | undefined;
  currentInput: UnknownRecord;
  channel: string;
  logger: { warn: (msg: string) => void };
}): Promise<UnknownRecord> {
  const { abiBuilder, currentInput, channel, logger } = params;

  let cognitiveState: UnknownRecord = {
    abiStatus: abiBuilder ? 'unavailable_or_invalid' : 'builder_not_injected',
    audience: 'public',
    perceptionSnapshot: { channel },
  };

  if (abiBuilder) {
    const abiResult = await abiBuilder.build({
      audience: 'public',
      currentInput,
      perceptionSnapshot: {
        channel,
      },
    });

    if (abiResult.status !== 'ok') {
      logger.warn(
        `ABI build failed: ${abiResult.reason}, using structured unified agent fallback`,
      );
    } else {
      const abi = abiResult.abi;
      const validation = validateAbiPayload(abi);

      if (validation.status === 'FAIL') {
        logger.warn(
          `ABI validation failed: ${JSON.stringify(validation.issues)}, using structured unified agent fallback`,
        );
      } else {
        cognitiveState = abi as unknown as UnknownRecord;
      }
    }
  }

  return cognitiveState;
}

import { AgentRuntimeContextService } from './agent-runtime';

export async function buildAgentRuntimeContext(params: {
  agentRuntime: AgentRuntimeContextService | undefined;
  workspaceId: string;
  channel: string;
  message: string;
  contactId?: string;
  allowedTools?: string[];
}): Promise<{ systemPromptBlock: string }> {
  if (!params.agentRuntime) {
    return { systemPromptBlock: '' };
  }
  return params.agentRuntime.buildContext({
    workspaceId: params.workspaceId,
    channel: params.channel,
    message: params.message,
    ...(params.contactId ? { contactId: params.contactId } : {}),
    ...(params.allowedTools !== undefined ? { allowedTools: params.allowedTools } : {}),
  });
}

export async function recordAgentRuntimeTurn(params: {
  agentRuntime: AgentRuntimeContextService | undefined;
  workspaceId: string;
  channel: string;
  userMessage: string;
  assistantMessage?: string;
  contactId?: string;
  intent?: string;
  confidence?: number;
  actions?: Array<{ toolName: string; success: boolean; result?: unknown }>;
}): Promise<void> {
  await params.agentRuntime?.recordTurnOutcome({
    workspaceId: params.workspaceId,
    channel: params.channel,
    userMessage: params.userMessage,
    ...(params.assistantMessage !== undefined ? { assistantMessage: params.assistantMessage } : {}),
    ...(params.contactId !== undefined ? { contactId: params.contactId } : {}),
    ...(params.intent !== undefined ? { intent: params.intent } : {}),
    ...(params.confidence !== undefined ? { confidence: params.confidence } : {}),
    ...(params.actions !== undefined ? { actions: params.actions } : {}),
  });
}

import OpenAI from 'openai';
import { StructuredLogger } from '../logging/structured-logger';
import { AuditService } from '../audit/audit.service';
import { PrismaService } from '../prisma/prisma.service';
import { AgentRuntimeContextService } from './agent-runtime';
import { RiskGateService } from './risk-class/risk-gate.service';
import { UnifiedAgentActionsService } from './unified-agent-actions.service';
import type { ToolArgs } from './unified-agent.types';

type UnknownRecord = Record<string, unknown>;

export interface ToolActionDeps {
  logger: StructuredLogger;
  actions: UnifiedAgentActionsService;
  riskGate?: RiskGateService;
  prisma: PrismaService;
  auditService: AuditService;
  agentRuntime?: AgentRuntimeContextService;
  openai: OpenAI | null;
  primaryBrainModel: string;
  fallbackBrainModel: string;
}

export function num(v: unknown, fb = 0): number {
  const n = Number(v);
  return Number.isFinite(n) ? Math.round(n) : fb;
}

export function actionSucceeded(result: unknown): boolean {
  if (!result || typeof result !== 'object' || Array.isArray(result)) {
    return false;
  }
  const record = result as Record<string, unknown>;
  return record.success === true || record.ok === true || record.executed === true;
}

export function buildAgentToolEnvelope(params: {
  agentRuntime: AgentRuntimeContextService | undefined;
  workspaceId: string;
  toolName: string;
}): { id: string; toolName: string; allowed: boolean } {
  return (
    params.agentRuntime?.buildToolEnvelope({
      workspaceId: params.workspaceId,
      toolName: params.toolName,
    }) ?? {
      id: 'agent-runtime-unavailable',
      toolName: params.toolName,
      allowed: true,
    }
  );
}

export async function executeToolAction(
  deps: ToolActionDeps,
  workspaceId: string,
  contactId: string,
  phone: string,
  tool: string,
  args: ToolArgs,
  context?: UnknownRecord,
): Promise<unknown> {
  deps.logger.log(`Executing tool: ${tool}`, { args });
  const envelope = buildAgentToolEnvelope({
    agentRuntime: deps.agentRuntime,
    workspaceId,
    toolName: tool,
  });

  switch (tool) {
    case 'send_message':
      return deps.actions.actionSendMessage(workspaceId, phone, args, context);
    case 'send_product_info':
      return deps.actions.actionSendProductInfo(workspaceId, phone, args, context);
    case 'create_payment_link': {
      const paymentAmount = num(args.amount);
      if (deps.riskGate && paymentAmount > 0) {
        const gateDecision = deps.riskGate.gatePaymentAction({
          amountCents: paymentAmount,
          reversible: true,
          target: 'lead',
        });
        if (gateDecision.verdict === 'block') {
          deps.logger.error(
            `R4 BLOCKED: create_payment_link — ${gateDecision.reason}`,
          );
          return {
            success: false,
            blocked: true,
            riskClass: gateDecision.classification.class,
            error: gateDecision.reason,
          };
        }
        if (gateDecision.verdict === 'warn') {
          deps.logger.warn(
            `Risk gate: payment ${gateDecision.classification.class} — ${gateDecision.reason}`,
          );
        }
      }
      const result = await deps.actions.actionCreatePaymentLink(
        workspaceId,
        phone,
        args,
        context,
      );
      try {
        await deps.prisma.$transaction(
          async (tx) => {
            await deps.auditService.logWithTx(tx, {
              workspaceId,
              action: 'AGENT_DISPATCHED_PAYMENT_LINK',
              resource: 'UnifiedAgent',
              resourceId: contactId,
              details: { tool, phone },
            });
          },
          { isolationLevel: 'ReadCommitted' },
        );
      } catch (auditError: unknown) {
        const auditMsg =
          auditError instanceof Error
            ? auditError.message
            : typeof auditError === 'string'
              ? auditError
              : 'unknown';
        deps.logger.warn(`Audit dispatch log failed: ${auditMsg}`);
      }
      return result;
    }
    case 'update_lead_status':
